const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={confirmed:'Подтверждено',rejected:'Отклонено',modified:'Изменено'},marker='РАССМОТРЕНИЕ ЗАМЕЧАНИЙ';
export function readExpertDecisions(text=''){const records=new Map();for(const m of text.matchAll(/^Замечание (\d+) — (Подтверждено|Отклонено|Изменено)\n([\s\S]*?)(?=^Замечание \d+ — |^СОБСТВЕННЫЕ ЗАМЕЧАНИЯ|^ВЫВОД ЭКСПЕРТА|$(?![\s\S]))/gm))records.set(Number(m[1]),{status:Object.keys(titles).find(k=>titles[k]===m[2]),comment:m[3].trim()});return records;}
export function withExpertDecision(text,index,status,comment){if(!titles[status])throw Error('Неизвестное решение');const records=readExpertDecisions(text);records.set(index,{status,comment:comment.trim()});const [body,...parts]=text.split('\n'+marker+'\n'),tail=parts.join('\n'+marker+'\n');let extra='';const matches=[tail.indexOf('СОБСТВЕННЫЕ ЗАМЕЧАНИЯ'),tail.indexOf('ВЫВОД ЭКСПЕРТА')].filter(i=>i>=0);if(matches.length)extra='\n\n'+tail.slice(Math.min(...matches));return body.trim()+'\n\n'+marker+'\n'+[...records].sort((a,b)=>a[0]-b[0]).map(([i,r])=>'Замечание '+i+' — '+titles[r.status]+'\n'+r.comment).join('\n\n')+extra;}
export function highlightedDocument(text,findings){const spans=[];for(let i=0;i<findings.length;i++){const q=findings[i].quote;if(!q)continue;const start=text.indexOf(q);if(start>=0)spans.push({start,end:start+q.length,index:i});}spans.sort((a,b)=>a.start-b.start||b.end-a.end);let end=0,html='';for(const s of spans){if(s.start<end)continue;html+=esc(text.slice(end,s.start))+'<mark tabindex="0" role="button" data-scroll-to="expert-finding-'+s.index+'" aria-label="Открыть замечание '+(s.index+1)+'">'+esc(text.slice(s.start,s.end))+'</mark>';end=s.end;}return html+esc(text.slice(end));}
export function expertReviewPanel(c){
 const latest=c.conclusions.at(-1),editable=!c.archivedAt&&(!c.queued||c.startedAt)&&c.role==='expert'&&latest?.status==='draft',records=readExpertDecisions(latest?.text||'');
 return `<section class="expert-review-panel"><p class="case-review-caption">Замечаний: ${c.run.findings.length}. Окончательное решение принимает эксперт.</p><div class="expert-review-layout"><div class="expert-document-column"><div class="case-column-heading"><h2>Документ</h2></div><div class="expert-document" id="expert-document">${highlightedDocument(c.document.text,c.run.findings)}</div>${editable?'<button type="button" class="btn compact expert-own-button" data-expert-own>Добавить своё замечание</button><p class="case-field-hint">Выделите фрагмент документа и нажмите кнопку.</p>':''}</div><div class="expert-findings-column"><div class="case-column-heading"><h2>Замечания и решения</h2></div><div class="expert-findings-list">${c.run.findings.map((f,i)=>`<article id="expert-finding-${i}" class="card expert-finding"><div class="expert-finding-head"><h3>Замечание ${i+1}</h3><span class="status" data-expert-status="${i+1}">${esc(titles[records.get(i+1)?.status]||'Не рассмотрено')}</span></div><p class="expert-finding-point">Пункт ${esc(f.point)}</p><blockquote>${esc(f.quote)}</blockquote><p class="expert-finding-explanation">${esc(f.explanation)}</p>${editable?`<label class="field"><span>Комментарий или исправленная редакция</span><textarea data-expert-comment="${i+1}" rows="2" maxlength="3000">${esc(records.get(i+1)?.comment||'')}</textarea></label><div class="expert-verdicts">${Object.entries(titles).map(([status])=>`<button type="button" class="btn compact" data-expert-verdict="${status}" data-index="${i+1}" aria-pressed="${records.get(i+1)?.status===status}">${({confirmed:'Подтвердить',rejected:'Отклонить',modified:'Изменить'})[status]}</button>`).join('')}</div>`:records.get(i+1)?.comment?'<p class="expert-record-comment"><strong>Комментарий эксперта:</strong> '+esc(records.get(i+1).comment)+'</p>':''}<details class="finding-evidence"><summary>Обоснование и рекомендации</summary>${f.editor?.proposal?'<p><strong>Проект правки ИИ:</strong> '+esc(f.editor.proposal)+'</p>':''}${f.editor?.requiresLegalReview?'<p>Проект требует сверки с применимыми нормами.</p>':''}${f.editor?.explanation?'<p><strong>Пояснение Редактора:</strong> '+esc(f.editor.explanation)+'</p>':''}${f.review?'<p><strong>Перепроверка ИИ:</strong> '+esc(({supported:'Выдержала перепроверку',contested:'Есть возражение',insufficient:'Недостаточно данных'})[f.review.verdict]||'Не выполнена')+'</p><p>'+esc(f.review.explanation||'')+'</p>'+((f.review.counterarguments||[]).length?'<ul>'+f.review.counterarguments.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':''):''}<p><strong>Решение автора документа:</strong> ${esc(({confirmed:'Подтверждено',modified:'Изменено',rejected:'Отклонено',pending:'Не рассмотрено'})[f.decision?.status]||'Не принято')}</p>${['explanation','proposal','comment','basis'].filter(k=>f.decision?.[k]).map(k=>'<p><strong>'+({explanation:'Объяснение',proposal:'Редакция автора',comment:'Комментарий автора',basis:'Основание автора'})[k]+':</strong> '+esc(f.decision[k])+'</p>').join('')}${(f.basis||[]).map(b=>'<blockquote>'+esc(b.quote)+'</blockquote>').join('')||'<p>Правовые основания ИИ не предоставлены.</p>'}</details></article>`).join('')||'<div class="card"><h3>Замечания ИИ отсутствуют</h3><p>Документ доступен для самостоятельной проверки.</p></div>'}</div></div></div></section>`;
}
export function conclusionTools(){return '<div class="conclusion-tools"><label class="field"><span>Вывод эксперта</span><select id="expert-outcome"><option value="">Выберите вывод</option><option>Коррупциогенные факторы выявлены</option><option>Коррупциогенные факторы не выявлены</option></select></label><label class="field"><span>Рекомендации</span><textarea id="expert-recommendations" rows="3" maxlength="5000"></textarea></label><button class="btn compact" type="button" data-expert-compose>Добавить в текст заключения</button><p id="expert-save-indicator" class="save-indicator" role="status">Черновик сохраняется автоматически каждые 30 секунд.</p><p id="expert-review-counter" role="status"></p><details class="conclusion-form-note"><summary>Оформление заключения</summary><p>Перед отправкой сверьте документ с официальной формой Минюста России.</p></details></div>';}
export function activateCaseTab(tab,root){if(!root||!['review','conclusion','discussion'].includes(tab))return false;for(const button of root.querySelectorAll('[data-case-tab]')){const selected=button.dataset.caseTab===tab;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;button.classList.toggle('primary',selected);}for(const panel of root.querySelectorAll('[data-case-panel]'))panel.hidden=panel.dataset.casePanel!==tab;return true;}
export function installExpertEditor({getCase,save,onDirty,onSaved,onTab}){let saving=false,selection='';const form=()=>document.getElementById('expert-draft-form');const update=()=>{const f=form(),c=getCase();if(!f||!c)return;const records=readExpertDecisions(f.elements.text.value);let done=0;for(let i=1;i<=c.run.findings.length;i++)if(records.has(i))done++;const counter=document.getElementById('expert-review-counter');if(counter)counter.textContent='Рассмотрено '+done+' из '+c.run.findings.length;const sign=document.querySelector('[data-action="expert-sign"]');if(sign)sign.disabled=done<c.run.findings.length;};const change=text=>{const f=form();if(!f)return;f.elements.text.value=text;f.elements.text.dispatchEvent(new Event('input',{bubbles:true}));update();};const message=text=>{const node=document.getElementById('expert-save-indicator');if(node)node.textContent=text;};
 document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-case-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const root=tab.closest('.expert-case-view'),tabs=[...root.querySelectorAll('[data-case-tab]')],index=tabs.indexOf(tab),next=e.key==='Home'?tabs[0]:e.key==='End'?tabs.at(-1):tabs[(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];e.preventDefault();if(activateCaseTab(next.dataset.caseTab,root)){onTab?.(root.dataset.caseId,next.dataset.caseTab);next.focus();}});
 document.addEventListener('selectionchange',()=>{const s=window.getSelection();if(s?.anchorNode?.parentElement?.closest('#expert-document'))selection=s.toString();});
 document.addEventListener('click',e=>{const tab=e.target.closest('[data-case-tab]');if(tab){const root=tab.closest('.expert-case-view');if(activateCaseTab(tab.dataset.caseTab,root))onTab?.(root.dataset.caseId,tab.dataset.caseTab);return;}const target=e.target.closest('[data-scroll-to]');if(target){const node=document.getElementById(target.dataset.scrollTo);node?.scrollIntoView({behavior:'smooth',block:'start'});node?.querySelector('textarea,button')?.focus({preventScroll:true});return;}const f=form();if(!f)return;const field=f.elements.text,b=e.target.closest('[data-expert-verdict]');if(b){const i=Number(b.dataset.index),comment=document.querySelector('[data-expert-comment="'+i+'"]')?.value||'';if(b.dataset.expertVerdict!=='confirmed'&&!comment.trim()){message('Добавьте комментарий для отклонения или изменения.');document.querySelector('[data-expert-comment="'+i+'"]')?.focus();return;}change(withExpertDecision(field.value,i,b.dataset.expertVerdict,comment));const badge=document.querySelector('[data-expert-status="'+i+'"]');if(badge)badge.textContent=titles[b.dataset.expertVerdict];for(const choice of document.querySelectorAll('[data-expert-verdict][data-index="'+i+'"]'))choice.setAttribute('aria-pressed',String(choice===b));}
 if(e.target.closest('[data-expert-own]')){if(!selection.trim()||!getCase().document.text.includes(selection)){message('Сначала выделите фрагмент текста документа.');return;}change(field.value+'\n\nСОБСТВЕННЫЕ ЗАМЕЧАНИЯ\nЦитата: «'+selection+'»\nОбъяснение и правовое основание: ');const root=field.closest('.expert-case-view');if(activateCaseTab('conclusion',root))onTab?.(root.dataset.caseId,'conclusion');field.focus();}
 if(e.target.closest('[data-expert-compose]')){const outcome=document.getElementById('expert-outcome').value,comment=document.getElementById('expert-recommendations').value;if(!outcome){document.getElementById('expert-outcome').focus();return;}change(field.value+'\n\nВЫВОД ЭКСПЕРТА\n'+outcome+'\nРекомендации: '+comment);}});
 document.addEventListener('input',e=>{if(e.target.closest('#expert-draft-form')){onDirty();update();}else if(e.target.matches('[data-expert-comment]')){onDirty();message('Для сохранения комментария выберите решение по замечанию.');}});document.addEventListener('keydown',e=>{const t=e.target.closest('[data-scroll-to]');if(t&&['Enter',' '].includes(e.key)){e.preventDefault();t.click();}});new MutationObserver(update).observe(document.getElementById('app'),{childList:true});
 setInterval(async()=>{const f=form(),c=getCase();if(!f||!c||saving||c.role!=='expert'||c.conclusions.at(-1)?.status!=='draft')return;const text=f.elements.text.value;if(!text.trim()||text===c.conclusions.at(-1).text)return;saving=true;try{const result=await save(c.id,text,Number(f.dataset.revision));if(f.isConnected){f.dataset.revision=String(result.revision);const b=document.querySelector('[data-action="expert-sign"]');if(b)b.dataset.revision=String(result.revision);message('Сохранено в '+new Date().toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow'})+' МСК');}onSaved(c.id,text,result,f);}catch(error){message('Не удалось сохранить: '+error.message+' Текст остаётся в черновике.');}finally{saving=false;}},30000);
}
